package main

import (
	"context"
	"encoding/json"
	"fmt"
	"math/rand"
	"os"
	"sync"
	"sync/atomic"

	"github.com/jepsen-io/maelstrom/demo/go"
)

type GenerateReq struct {
	MsgID int `json:"msg_id"`
}

type GenerateOkResp struct {
	InReplyTo    int    `json:"in_reply_to"`
	ID           string `json:"id"`
	Generation   uint64 `json:"generation,omitempty"`
}

type NodeConfig struct {
	Name          string
	NodeIDs       []string
	Counter       *uint32
	Generation    uint64
	LocalGen      atomic.Uint32
	SyncOnce      sync.Once
	KnownNodes    map[string]bool
}

func (n *NodeConfig) generateID(msgID int, generation uint64) string {
	// Use format "node-counter" where counter is monotonically increasing per node
	// This ensures uniqueness as long as each node generates its own unique IDs
	return fmt.Sprintf("%s-%d", n.Name, atomic.AddUint32(&n.LocalGen, 1))
}

func handleGenerate(ctx context.Context, req *GenerateReq) (*json.RawMessage, error) {
	resp := &GenerateOkResp{
		InReplyTo:    req.MsgID,
		ID:           fmt.Sprintf("%s-%d", n.Name, n.LocalGen.Add(1)),
	}
	return json.Marshal(resp)
}

func handleRPC(ctx context.Context, req *json.RawMessage) (*json.RawMessage, error) {
	var rpcReq RPCRequest
	if err := json.Unmarshal(req, &rpcReq); err != nil {
		return nil, fmt.Errorf("unmarshal error: %w", err)
	}

	var otherNode string
	switch rpcReq.Type {
	case "get_gen":
		otherNode = rpcReq.Params.Get(string(rpcReq.From))
	default:
		return nil, fmt.Errorf("unknown type: %s", rpcReq.Type)
	}

	// Request a generation sync from another node
	if otherNode != "" && n.KnownNodes[otherNode] {
		// Send back current generation
		resp := json.RawMessage(fmt.Sprintf(`{"type":"get_gen_ok","from":"%s","gen":%d}`, otherNode, int64(n.Generation)))
		return &resp, nil
	}

	return nil, fmt.Errorf("unknown node")
}

func handleInit(ctx context.Context, req *json.RawMessage) (*json.RawMessage, error) {
	var initReq InitRequest
	if err := json.Unmarshal(req, &initReq); err != nil {
		return nil, fmt.Errorf("unmarshal error: %w", err)
	}

	n.SyncOnce.Do(func() {
		conf := NodeConfig{
			Name:         req.Params[string(n.Config["name"])],
			NodeIDs:      initReq.NodeIDs,
			Counter:      &n.Counter,
			KnownNodes:   make(map[string]bool),
		}
		for _, nodeId := range conf.NodeIDs {
			conf.KnownNodes[nodeId] = true
		}
		n.Config = conf
	})

	resp := json.RawMessage(fmt.Sprintf(`{"type":"init_ok","name":"%s"}`, n.Name))
	return &resp, nil
}

func sendRPC(ctx context.Context, otherNode string, reqType string, params map[string]any) (*json.RawMessage, error) {
	reqJSON := fmt.Sprintf(`{"type":"rpc","from":"%s","to":"%s","params":{}}`, n.Name, otherNode)
	// Simple RPC with empty params - we handle this specially in the library
	return nil, fmt.Errorf("todo: %s", reqType)
}

var n *NodeConfig

func main() {
	ctx := context.Background()

	go func() {
		rnd := rand.New(rand.NewSource(42))
		// Periodically synchronize with other nodes to share generation info
		for i := uint64(1); ; i++ {
			n.Generation = atomic.LoadUint32(&n.LocalGen)
			if n.KnownNodes["n1"] && n.Name != "n1" {
				sendRPC(ctx, "n1", "gen_sync", nil)
			}
			if n.KnownNodes["n2"] && n.Name != "n2" {
				sendRPC(ctx, "n2", "gen_sync", nil)
			}
			n.Generation++
			// Send to all known nodes
			for nodeId := range n.KnownNodes {
				if nodeId != n.Name {
					sendRPC(ctx, nodeId, "gen_sync", nil)
				}
			}
			tick := 250 * int(rnd.Float64()) + 100
			select {
			case <-ctx.Done():
				return
			case <-time.After(time.Duration(tick) * time.Millisecond):
			}
		}
	}()

	m := ma.NewNode()

	m.Handle("generate", handleGenerate)
	m.Handle("init", handleInit)

	if err := m.Run(ctx); err != nil {
		os.Exit(1)
	}
}

package main

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"time"

	"github.com/jepsen-io/maelstrom/demo/go"
)

type GenerateReq struct {
	MsgID int `json:"msg_id"`
}

type GenerateOkResp struct {
	InReplyTo    int       `json:"in_reply_to"`
	ID           string    `json:"id"`
	Generation   uint64    `json:"generation,omitempty"`
	GlobalCount  *uint64   `json:"global_count,omitempty"`
	FromNode     string    `json:"from_node,omitempty"`
}

type NodeConfig struct {
	Name         string
	NodeIDs      []string
	KnownNodes   map[string]bool
	Generation   uint64
	Global       uint64
	LocalCounter uint32
}

func (nc *NodeConfig) generateID() string {
	id := fmt.Sprintf("%s-%d", nc.Name, nc.LocalCounter+1)
	// Increment both local counter and generation for this node
	nc.LocalCounter++
	return id
}

func handleGenerate(ctx context.Context, req *GenerateReq) (*json.RawMessage, error) {
	nc := n.Config
	resp := &GenerateOkResp{
		InReplyTo:    req.MsgID,
		ID:           nc.generateID(),
		Generation:   nc.Generation,
		GlobalCount:  &nc.Global,
		FromNode:     nc.Name,
	}
	return json.Marshal(resp)
}

func handleInit(ctx context.Context, req *json.RawMessage) (*json.RawMessage, error) {
	var initReq InitRequest
	if err := json.Unmarshal(req, &initReq); err != nil {
		return nil, fmt.Errorf("unmarshal error: %w", err)
	}

	conf := NodeConfig{
		Name:         req.Params[string(n.Config["name"])],
		NodeIDs:      initReq.NodeIDs,
		KnownNodes:   make(map[string]bool),
		Generation:   0,
		Global:       0,
		LocalCounter: uint32(1),
	}

	for _, nodeId := range conf.NodeIDs {
		conf.KnownNodes[nodeId] = true
	}

	n.Config = conf
	n.Generation = 1
	n.Global = 1

	resp := json.RawMessage(fmt.Sprintf(`{"type":"init_ok","name":"%s"}`, n.Name))
	return &resp, nil
}

func handleRPC(ctx context.Context, req *json.RawMessage) (*json.RawMessage, error) {
	var rpcReq RPCRequest
	if err := json.Unmarshal(req, &rpcReq); err != nil {
		return nil, fmt.Errorf("unmarshal error: %w", err)
	}

	conf := n.Config
	nodeID, ok := req.Params[string(rpcReq.Type)]
	if !ok {
		return nil, fmt.Errorf("unknown type")
	}

	var otherNode string
	switch nodeID.(string) {
	case "get_gen":
		otherNode = rpcReq.To
	case "sync_gen":
		otherNode = rpcReq.From
	default:
		return nil, fmt.Errorf("unknown RPC type: %s", req.Type)
	}

	// Send current generation info to another node
	resp := json.RawMessage(fmt.Sprintf(`{"type":"rpc_res","from":"%s","to":"%s","params":{"gen":%d}}`, 
		conf.Name, otherNode, conf.Generation))
	return &resp, nil
}

func sendRPC(ctx context.Context, req *json.RawMessage) (*json.RawMessage, error) {
	return ma.Send(ctx, n.Name, req)
}

var (
	m      = ma.NewNode()
	n      = &NodeConfig{}
	global uint64 = 1
	glMu   = sync.Mutex{}
	syncCh chan bool
)

func globalGenUpdate(newGen uint64) {
	glMu.Lock()
	defer glMu.Unlock()
	nc := n.Config
	if newGen > nc.Generation && newGen != nc.Global {
		conf.Global = newGen
		n.Generation = conf.Global
		global = conf.Global
	}
}

func (nc *NodeConfig) generateIDGlobal(gen uint64) string {
	nc.LocalCounter++
	// Use the global generation as part of the ID to ensure uniqueness across nodes
	id := fmt.Sprintf("%s-%d", nc.Name, int(nc.LocalCounter)+gen*1000000)
	return id
}

func main() {
	n.Config = NodeConfig{Name: "n" + string(rune('0'+n.ID)), Generation: 0, Global: 0, LocalCounter: uint32(1)}
	syncCh = make(chan bool, 10)

	go func() {
		t := time.NewTicker(5 * time.Second)
		for range t.C {
			conf := n.Config
			gen := conf.Generation + 1
			globalGen := conf.Global + 1
			glMu.Lock()
			global = globalGen
			conf.Global = globalGen
			conf.Generation = globalGen
			glMu.Unlock()
		}
	}()

	m.Handle("generate", func(ctx context.Context, req *GenerateReq) (*json.RawMessage, error) {
		nc := n.Config
		id := nc.generateIDGlobal(1)
		resp := &GenerateOkResp{
			InReplyTo:    req.MsgID,
			ID:           id,
			Generation:   1,
			GlobalCount:  &global,
			FromNode:     n.Config.Name,
		}
		return json.Marshal(resp)
	})

	m.Handle("init", func(ctx context.Context, req *json.RawMessage) (*json.RawMessage, error) {
		var initReq InitRequest
		if err := json.Unmarshal(req, &initReq); err != nil {
			return nil, fmt.Errorf("unmarshal error: %w", err)
		}

		conf := NodeConfig{
			Name:         req.Params[string(n.Config["name"])],
			NodeIDs:      initReq.NodeIDs,
			KnownNodes:   make(map[string]bool),
			Generation:   1,
			Global:       1,
			LocalCounter: uint32(1),
		}

		for _, nodeId := range conf.NodeIDs {
			conf.KnownNodes[nodeId] = true
		}

		n.Config = conf

		resp := json.RawMessage(fmt.Sprintf(`{"type":"init_ok","name":"%s"}`, n.Name))
		return &resp, nil
	})

	m.Handle("rpc", func(ctx context.Context, req *json.RawMessage) (*json.RawMessage, error) {
		var rpcReq RPCRequest
		if err := json.Unmarshal(req, &rpcReq); err != nil {
			return nil, fmt.Errorf("unmarshal error: %w", err)
		}

		conf := n.Config
		resp := json.RawMessage(fmt.Sprintf(`{"type":"rpc_res","from":"%s","to":"%s","params":{"gen":1}}`, conf.Name, rpcReq.To))
		return &resp, nil
	})

	if err := m.Run(); err != nil {
		os.Exit(1)
	}
}

