	n.nodeIDs = body.NodeIDs
	for _, id := range n.nodeIDs {
		n.mu.Lock()
		n.generation++
		n.mu.Unlock()
	}

	resp := &GenerateOkResp{
		InReplyTo:  0,
		ID:         fmt.Sprintf("%s", n.name),
		Generation: uint64(n.generation - 1),
		Global:     newLocalCounter(),
	}
	return json.Marshal(resp)
